[metadata] {"type": "text", "file": {"filePath": "/workspace/repo/crates/libs/rdl/src/error.rs", "content": "pub struct Error {
    pub message: String,
    pub file_name: String,
    pub line: usize,
    pub column: usize,
}

impl Error {
    pub fn new(message: &str, file_name: &str, line: usize, column: usize) -> Self {
        Self {
            message: message.to_string(),
            file_name: file_name.to_string(),
            line,
            column,
        }
    }
}

impl std::error::Error for Error {}

impl std::fmt::Debug for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        std::fmt::Display::fmt(self, f)
    }
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        if self.line != 0 || self.column != 0 {
            write!(
                f,
                "\nerror: {}\n --> {}:{}:{}",
                &self.message,
                &self.file_name,
                self.line,
                self.column + 1
            )
        } else if self.file_name.is_empty() {
            write!(f, "\nerror: {}", &self.message)
        } else {
            write!(f, "\nerror: {}\n --> {}", &self.message, &self.file_name)
        }
    }
}
