/// A single member appearing inside an interface body.  In addition to regular
/// methods, interface bodies support property (`Name: Type;`) and event
/// (`event Name: HandlerType;`) shorthands that expand into SpecialName method
/// pairs during encoding.
#[derive(Debug)]
pub enum InterfaceMember {
    Method(Method),
    Property(Property),
    Event(Event),
}

/// A property shorthand declaration: `[#[get] | #[set]] Name: Type;`.
///
/// Without any attribute both a getter and a setter are generated; `#[get]`
/// generates only a getter (read-only) and `#[set]` only a setter (write-only).
