        let emit_getter = !has_set;
        let emit_setter = !has_get;

        let ty = self.encode_type(&property.ty)?;
        if item.winrt {
            self.validate_type_is_winrt(&property.ty, &ty)?;
        }

        if emit_getter {
            let name = format!("get_{}", property.name);
            self.encode_special_method(
