/// Emits all interface members, converting SpecialName `get_`/`put_` method pairs
/// into property shorthands and `add_`/`remove_` pairs into event shorthands.
/// Any method not consumed by a shorthand falls back to the regular method form.
fn write_members(
    namespace: &str,
    item: &metadata::reader::TypeDef,
    generics: &[metadata::Type],
) -> Result<Vec<TokenStream>, Error> {
    let methods: Vec<metadata::reader::MethodDef> = item.methods().collect();
    let mut consumed = vec![false; methods.len()];
    let mut members = Vec::new();

    for i in 0..methods.len() {
        if consumed[i] {
            continue;
        }

        let method = &methods[i];
        let name = method.name();
        let is_special = method
            .flags()
            .contains(metadata::MethodAttributes::SpecialName);

        if is_special {
            // Property getter (`get_Name`) — pair with a `put_Name` setter if present.
            if let Some(prop) = name.strip_prefix("get_") {
                consumed[i] = true;
                let setter = find_unconsumed(&methods, &consumed, i, &format!("put_{prop}"));
                if let Some(j) = setter {
                    consumed[j] = true;
                }
                members.push(write_property(namespace, prop, method, setter.is_some(), generics));
                continue;
            }

            // Property setter (`put_Name`) — only reached when no matching getter
            // precedes it, so this is a write-only property.
            if let Some(prop) = name.strip_prefix("put_") {
                consumed[i] = true;
                let getter = find_unconsumed(&methods, &consumed, i, &format!("get_{prop}"));
                if let Some(j) = getter {
                    consumed[j] = true;
                    members.push(write_property(namespace, prop, &methods[j], true, generics));
                } else {
                    members.push(write_set_property(namespace, prop, method, generics));
                }
                continue;
            }

            // Event add (`add_Name`) — pair with the matching `remove_Name`.
            if let Some(evt) = name.strip_prefix("add_") {
                if let Some(j) = find_unconsumed(&methods, &consumed, i, &format!("remove_{evt}")) {
                    consumed[i] = true;
                    consumed[j] = true;
                    members.push(write_event(namespace, evt, method, generics));
                    continue;
                }
            }

            // Event remove (`remove_Name`) encountered before its add — pair it up.
            if let Some(evt) = name.strip_prefix("remove_") {
                if let Some(j) = find_unconsumed(&methods, &consumed, i, &format!("add_{evt}")) {
                    consumed[i] = true;
                    consumed[j] = true;
                    members.push(write_event(namespace, evt, &methods[j], generics));
                    continue;
                }
            }
        }

        consumed[i] = true;
        members.push(write_method(namespace, method, generics)?);
    }

    Ok(members)
}

/// Finds the index of an as-yet-unconsumed method named `name`, searching forward
/// from `from` and wrapping around to the beginning.
fn find_unconsumed(
    methods: &[metadata::reader::MethodDef],
    consumed: &[bool],
    from: usize,
    name: &str,
) -> Option<usize> {
    let len = methods.len();
    for offset in 1..=len {
        let idx = (from + offset) % len;
        if !consumed[idx] && methods[idx].name() == name {
            return Some(idx);
        }
    }
    None
}

/// Writes a property shorthand for a getter (`Name: Type;` or `#[get] Name: Type;`).
/// The property type is taken from the getter's return type.
fn write_property(
    namespace: &str,
    prop: &str,
    getter: &metadata::reader::MethodDef,
    has_setter: bool,
    generics: &[metadata::Type],
) -> TokenStream {
    let name = write_ident(prop);
    let ty = write_type(namespace, &getter.signature(generics).return_type);

    if has_setter {
        quote! { #name: #ty; }
    } else {
        quote! { #[get] #name: #ty; }
    }
}

/// Writes a write-only property shorthand (`#[set] Name: Type;`).  The property
/// type is taken from the setter's single (non-`self`) parameter.
fn write_set_property(
    namespace: &str,
    prop: &str,
    setter: &metadata::reader::MethodDef,
    generics: &[metadata::Type],
) -> TokenStream {
    let name = write_ident(prop);
    let signature = setter.signature(generics);
    let ty = signature
        .types
        .first()
        .map(|ty| write_type(namespace, ty))
        .unwrap_or_else(|| quote! { void });

    quote! { #[set] #name: #ty; }
}

/// Writes an event shorthand (`event Name: HandlerType;`).  The handler type is
/// taken from the add method's single (non-`self`) parameter.
fn write_event(
    namespace: &str,
    evt: &str,
    add: &metadata::reader::MethodDef,
    generics: &[metadata::Type],
) -> TokenStream {
    let name = write_ident(evt);
    let signature = add.signature(generics);
    let handler_ty = signature
        .types
        .first()
        .map(|ty| write_type(namespace, ty))
        .unwrap_or_else(|| quote! { void });

    quote! { event #name: #handler_ty; }
